INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (101, 'Java 中 HashMap 的底层实现原理与扩容机制是怎样的？', 'HashMap 在 JDK 1.8 采用【数组 + 链表 + 红黑树】实现。默认初始容量为 16，负载因子为 0.75。通过 key 的 hashCode 计算二次扰动值确定数组槽位。当单链表节点数达到 8 且数组总长度达到 64 时，链表树化为红黑树以优化查询时间复杂度从 O(n) 至 O(log n)；节点数减少至 6 时退化为链表。当元素总数超过阈值（容量 × 0.75）时触发 2 倍扩容，扩容时通过高低位指针（e.hash & oldCap）重新映射位置，避免了 rehash。', 'HashMap,哈希表,底层原理,扩容机制,红黑树,链表,数组,负载因子,树化,哈希桶,Java集合', 'Java与后端开发', 1, 'it-101', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (102, 'ConcurrentHashMap 是如何保证线程安全的？JDK 7 与 JDK 8 有何区别？', 'JDK 1.7 中采用【分段锁 Segment】机制，继承自 ReentrantLock，并发度取决于 Segment 数组大小（默认16）。而在 JDK 1.8 中彻底摒弃了 Segment，改用【Node 数组 + CAS + synchronized】实现细粒度锁。仅在插入新节点时通过 CAS 保证原子性；哈希冲突时只锁住当前哈希桶的头节点（Node），大大减少了锁竞争。统计元素数量时使用 CounterCell 分散热点写入。', 'ConcurrentHashMap,线程安全,分段锁,Segment,CAS,synchronized,并发容器,哈希冲突', 'Java与后端开发', 1, 'it-102', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (103, 'Java 中基本数据类型与包装类型有什么区别？什么是自动装箱与拆箱？', 'Java 有 8 种基本类型（byte, short, int, long, float, double, char, boolean）。区别：1. 存储位置：基本类型局部变量存放在栈中，包装类型是对象存放在堆中；2. 默认值：基本类型有默认零值，包装类型默认为 null，适合在实体类和数据库映射中使用；3. 泛型支持：泛型只能使用包装类。自动装箱（如 int ➔ Integer）底层调用 `Integer.valueOf()`，自动拆箱（Integer ➔ int）调用 `intValue()`。Integer 内部维护了 -128 到 127 的常量缓存池。', '基本类型,包装类型,装箱,拆箱,自动装箱,自动拆箱,Integer缓存池,基本数据类型', 'Java与后端开发', 1, 'it-103', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (104, 'String、StringBuilder 与 StringBuffer 有什么区别？为什么 String 不可变？', '1. 不可变性：String 被 final 修饰且底层 byte 数组亦为 private final，不可被修改。不可变保证了哈希码缓存不变、字符串常量池复用、线程安全以及类加载与网络通信的安全性。2. 可变性与线程安全：StringBuilder 是可变字符序列，非线程安全，单线程字符拼接性能最高；StringBuffer 方法使用 synchronized 修饰，线程安全但有同步开销。频繁拼接字符串强烈推荐使用 StringBuilder。', 'String,StringBuilder,StringBuffer,不可变,字符串拼接,线程安全,常量池', 'Java与后端开发', 1, 'it-104', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (105, 'Java 反射机制的核心原理是什么？有哪些应用场景与性能开销？', '反射允许程序在运行时动态获取任意类的完整结构（类名、修饰符、字段、方法、注解）并动态调用方法或修改私有成员。核心类包括 Class、Method、Field、Constructor。底层通过 JVM native 方法或动态生成字节码调用。广泛应用于 Spring IoC 容器依赖注入、MyBatis ORM 映射、RPC 序列化框架及动态代理。反射会绕过编译器优化并产生额外类型安全校验，高频场景应适当做 Method 缓存或采用 MethodHandle/ReflectASM 优化。', '反射,反射机制,Class,Method,动态调用,性能开销,私有属性,获取类信息', 'Java与后端开发', 1, 'it-105', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (106, 'Java 异常体系结构是怎样的？Checked 异常与 Runtime 异常有什么区别？', '所有异常根类为 `Throwable`，分为两大子类：`Error`（严重硬件/JVM错误，如 OOM、StackOverflow，程序不应捕获）与 `Exception`（程序自身可处理的异常）。Exception 又分为：1. Checked 异常（受检异常，如 IOException, SQLException），编译器强制要求 try-catch 或 throws 显式处理；2. Unchecked 异常（非受检运行时异常，继承自 `RuntimeException`，如 NullPointerException, IndexOutOfBoundsException），通常由逻辑缺陷引起，编译器不强制处理。', '异常,异常体系,Throwable,Exception,Error,受检异常,运行时异常,RuntimeException,OOM', 'Java与后端开发', 1, 'it-106', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (107, 'Java 线程池的核心参数有哪些？完整工作流程与拒绝策略是怎样的？', 'ThreadPoolExecutor 包含 7 大核心参数：corePoolSize（核心线程数）、maximumPoolSize（最大线程数）、keepAliveTime（非核心空闲存活时间）、unit（时间单位）、workQueue（任务阻塞队列）、threadFactory（线程工厂）、handler（拒绝策略）。工作流程：新任务到来 ➔ 核心线程未满则创建核心线程 ➔ 核心线程已满则入队 ➔ 队列已满则创建非核心线程至最大数 ➔ 达到最大线程数且队列仍满则触发拒绝策略（AbortPolicy 抛异常、CallerRunsPolicy 调用者线程执行、DiscardPolicy 丢弃、DiscardOldestPolicy 丢弃队列最老任务）。', '线程池,核心参数,阻塞队列,拒绝策略,工作流程,ThreadPoolExecutor,线程数', 'Java与后端开发', 1, 'it-107', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (108, 'ThreadLocal 底层原理是什么？为什么会发生内存泄漏？如何正确避免？', 'ThreadLocal 用于线程间数据隔离。每个 Thread 内部维护一个 `ThreadLocalMap`，其 Entry 的 Key 为 ThreadLocal 的弱引用（WeakReference），Value 为真实变量的强引用。若外层 ThreadLocal 强引用断开，Key 会被 GC 回收变为 null，但 Value 是强引用且线程长期存活（如在线程池中），导致 Value 无法被回收产生内存泄漏。正确使用：使用完毕后必须在 `finally` 代码块中显式调用 `threadLocal.remove()` 清理。', 'ThreadLocal,内存泄漏,ThreadLocalMap,弱引用,线程隔离,remove方法', 'Java与后端开发', 1, 'it-108', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (109, 'JVM 运行时数据区是如何划分的？堆与栈的作用和区别是什么？', 'JVM 内存分为 5 大区域：1. 程序计数器（记录线程执行字节码指令行号，私有）；2. 虚拟机栈（存储局部变量表、操作数栈、动态链接、方法出口，私有）；3. 本地方法栈（为 Native 方法服务，私有）；4. 堆（Heap，存放所有对象实例与数组，垃圾回收主战场，共享）；5. 方法区/元空间（MetaSpace，存储类元信息、常量、静态变量，共享，JDK8移至本地内存）。堆是解决数据存储问题，栈是解决程序运行逻辑问题。', 'JVM,运行时数据区,堆,栈,方法区,程序计数器,元空间,内存划分,MetaSpace', 'Java与后端开发', 1, 'it-109', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (110, 'JVM 垃圾回收算法有哪些？G1 与 ZGC 收集器有什么核心特点？', '基础回收算法包括：标记-清除（易产生碎片）、标记-复制（无碎片但浪费一半空间，用于年轻代）、标记-整理（无碎片用于老年代）。G1 收集器将堆划分为等大小的独立 Region（Region 动态扮演 Eden/Survivor/Old/Humongous），采用增量并发标记和复制算法，允许用户设定目标最大停顿时间（MaxGCPauseMillis）并优先回收价值最大的 Region。ZGC 则是低延迟垃圾回收器，基于着色指针（Colored Pointer）与读屏障（Load Barrier）实现并发标记与并发整理，STW 停顿控制在毫秒级以内。', '垃圾回收,垃圾回收GC,G1,ZGC,标记清除,标记复制,标记整理,STW,Region,着色指针', 'Java与后端开发', 1, 'it-110', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (111, 'Java 中对象的强引用、软引用、弱引用与虚引用有什么区别？', '1. 强引用（StrongReference）：最常见的普通引用，只要强引用还在，垃圾回收器绝不会回收该对象，内存不足报 OOM；2. 软引用（SoftReference）：内存充足时不回收，系统内存即将溢出前进行二次回收，常用于实现内存敏感的高速缓存；3. 弱引用（WeakReference）：无论内存是否充足，只要触发垃圾回收必定被清理，典型应用为 ThreadLocalMap 与 WeakHashMap；4. 虚引用（PhantomReference）：形同虚设，必须配合引用队列（ReferenceQueue）使用，仅用于跟踪对象被回收的状态与资源清理。', '强引用,软引用,弱引用,虚引用,Reference,引用类型,引用队列,垃圾回收', 'Java与后端开发', 1, 'it-111', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (112, 'Java 8 Stream API 的核心概念与常用操作有哪些？使用上有何陷阱？', 'Stream 是对集合进行函数式高阶计算的抽象流水线。操作分为：中间操作（无状态 filter/map，有状态 distinct/sorted/limit，具备惰性求值特性）与终端操作（forEach/collect/reduce/count，触发真正计算）。避坑指南：1. Stream 只能消费一次，重复消费报 IllegalStateException；2. parallelStream 并行流默认使用全局 ForkJoinPool.commonPool，涉及 I/O 密集型任务会造成全局线程阻塞；3. 避免在 Stream 中修改外部共享变量产生竞态条件。', 'Stream,流式计算,Lambda,中间操作,终端操作,惰性求值,parallelStream,函数式编程', 'Java与后端开发', 1, 'it-112', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (113, 'Spring 框架中 IoC（控制反转）和 DI（依赖注入）的核心思想是什么？', 'IoC（Inversion of Control，控制反转）是一种将对象的创建、组装和生命周期管理从业务代码剥离交由容器（BeanFactory / ApplicationContext）统一托管的软件设计思想。DI（Dependency Injection，依赖注入）是 IoC 的具体实现手段，容器在运行时根据配置（注解如 @Autowired, @Resource）将依赖组件自动注入到目标对象中。优势在于：降低类与类之间的直接耦合，极大提升模块可测试性（方便 Mock 单元测试）与扩展性。', 'IoC,控制反转,依赖注入,依赖注入DI,Spring核心,BeanFactory,解耦', 'Spring与微服务', 1, 'it-113', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (114, 'Spring Bean 的生命周期是怎样的？从实例化到销毁经历了哪些阶段？', 'Spring Bean 完整生命周期包括：1. 实例化（Instantiation）：反射创建对象；2. 属性填充（Populate）：依赖注入赋值；3. Aware 接口回调（BeanNameAware, BeanFactoryAware, ApplicationContextAware）；4. 初始化前处理（BeanPostProcessor.postProcessBeforeInitialization）；5. 初始化（@PostConstruct ➔ InitializingBean.afterPropertiesSet ➔ 自定义 init-method）；6. 初始化后处理（BeanPostProcessor.postProcessAfterInitialization，AOP 代理对象在此生成）；7. 投入使用；8. 销毁（@PreDestroy ➔ DisposableBean.destroy ➔ destroy-method）。', 'Spring,Bean,生命周期,生命周期流程,Bean生命周期,实例化,初始化,销毁,BeanPostProcessor', 'Spring与微服务', 1, 'it-114', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (115, 'Spring 中的 Bean 是线程安全的吗？默认的作用域有哪些？', 'Spring 单例 Bean（Singleton）本身并不提供任何线程安全保证。如果 Bean 是无状态的（如标准的 Service、Dao、Controller，只包含逻辑不维护实例变量），则是线程安全的；如果 Bean 包含有状态的可变实例字段，多线程并发修改会产生线程安全问题。解决方案：1. 改用局部变量；2. 结合 ThreadLocal 保存线程私有变量；3. 声明为原型作用域 `@Scope("prototype")`。Spring 支持 5 种作用域：singleton、prototype，以及 Web 环境下的 request、session、application。', 'Spring,Bean,线程安全,作用域,单例,Singleton,Prototype,有状态Bean,无状态', 'Spring与微服务', 1, 'it-115', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (116, 'Spring AOP 的底层实现原理是什么？JDK 动态代理与 CGLIB 有何区别？', 'Spring AOP 基于动态代理机制，在运行时为目标类生成代理对象并在切点处织入增强逻辑。两种实现机制：1. JDK 动态代理：基于反射与 `InvocationHandler`，要求目标类必须实现至少一个接口，生成的代理类继承自 `Proxy`；2. CGLIB 代理：基于 ASM 字节码生成框架，通过动态生成目标类的子类覆盖非 final 方法进行拦截增强。Spring Boot 2.x/3.x 默认全面启用 CGLIB 代理（`proxyTargetClass=true`），以统一对接口和普通类的代理行为。', 'AOP,切面编程,动态代理,JDK动态代理,CGLIB,InvocationHandler,字节码增强', 'Spring与微服务', 1, 'it-116', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (117, 'Spring 事务传播行为有哪些？哪些常见场景会导致 @Transactional 事务失效？', 'Spring 支持 7 种传播行为，最常用的是 `REQUIRED`（支持当前事务，没有则新建）与 `REQUIRES_NEW`（挂起当前事务并开启独立新事务）。常见失效场景：1. 同类中非事务方法通过 `this.xxx()` 自调用事务方法（绕过了代理对象）；2. 方法修饰符非 `public`；3. 异常被内部 `try-catch` 吞掉未向外抛出；4. 抛出的异常与 `rollbackFor` 不匹配（默认只回滚 RuntimeException 和 Error，检查异常需指定 `rollbackFor=Exception.class`）；5. 数据库存储引擎不支持事务（如 MyISAM）；6. 异步多线程执行业务导致事务连接解绑。', 'Spring,事务,Spring事务,事务失效,失效场景,Transactional,事务传播,自调用', 'Spring与微服务', 1, 'it-117', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (118, 'Spring Boot 自动装配原理是什么？@EnableAutoConfiguration 是如何工作的？', 'Spring Boot 自动装配通过 `@EnableAutoConfiguration` 导入 `AutoConfigurationImportSelector`。在应用启动时，该 Selector 读取所有 jar 包中 `META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports`（Spring Boot 3.x）或 `spring.factories`（2.x）中配置的自动配置类列表。然后结合各自动配置类上的条件注解（如 `@ConditionalOnClass`、`@ConditionalOnMissingBean`、`@ConditionalOnProperty`）进行条件筛选，仅在符合当前运行环境依赖时才将对应的 Bean 注入 Spring 容器，实现“约定大于配置、开箱即用”。', '自动装配,自动配置,EnableAutoConfiguration,spring.factories,条件注解,ConditionalOnClass,SpringBoot原理', 'Spring与微服务', 1, 'it-118', NOW())
