VALUES (119, '@SpringBootApplication 注解由哪三个核心注解组合而成？各自作用是什么？', '`@SpringBootApplication` 是一个复合注解，核心由以下三者组合而成：1. `@SpringBootConfiguration`：继承自 `@Configuration`，标识当前类为配置类，可向容器注册 Bean；2. `@EnableAutoConfiguration`：开启 Spring Boot 的自动装配机制，根据 classpath 依赖智能加载预置组件；3. `@ComponentScan`：配置组件扫描路径，默认扫描当前启动类所在包及其所有子包下的 `@Component`、`@Service`、`@Repository`、`@Controller` 等注解并注册为 Bean。', 'SpringBootApplication,SpringBoot,注解,核心注解,组合注解,注解组成,SpringBootConfiguration,EnableAutoConfiguration,ComponentScan', 'Spring与微服务', 1, 'it-119', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (120, 'Spring Cloud 微服务体系的核心组件有哪些？各自承担什么职责？', '主流 Spring Cloud 微服务核心包括 5 大模块：1. 服务注册与发现中心（Nacos / Eureka / Consul）：负责微服务实例的元数据登记、心跳健康检查与动态服务发现；2. 服务网关（Spring Cloud Gateway）：作为全站流量统一入口，提供路由转发、统一鉴权、限流与跨域处理；3. 声明式远程调用（OpenFeign）：基于注解与 HTTP 的客户端声明式 RPC 通信；4. 熔断降级与流量防护（Sentinel / Resilience4j）：提供高并发防雪崩、流量整形、热点参数限流；5. 分布式配置中心（Nacos Config / Spring Cloud Config）：统一集中管理各服务配置并支持动态热刷新。', 'SpringCloud,微服务,微服务体系,微服务架构,核心组件,组件,组件有哪些,分布式架构', 'Spring与微服务', 1, 'it-120', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (121, 'Nacos 作为注册中心和配置中心的核心工作原理是什么？与 Eureka 有何不同？', '1. 服务注册：客户端启动时向 Nacos 发送 HTTP/gRPC 请求上报服务元数据，临时实例通过心跳周期上报健康状态（5s一次），持久实例由服务端主动探活。Nacos 服务端采用 Copy-On-Write 内存列表管理实例变更并通过 UDP/gRPC 实时推送给订阅方；2. 配置中心：客户端采用基于长轮询（Long Polling）与 gRPC 的监听机制，配置变更时 MD5 校验不匹配则主动拉取最新内容并刷新环境上下文。对比 Eureka：Eureka 只支持 AP 模型与轮询同步；Nacos 同时支持 CP（Raft协议）和 AP（Distro协议）动态切换，具备更高的性能与动态推送能力。', 'Nacos,注册中心,配置中心,长轮询,心跳机制,Eureka对比,AP模式,CP模式,动态刷新', 'Spring与微服务', 1, 'it-121', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
