VALUES (124, 'Spring Cloud Gateway 核心架构与过滤器链（Filter Chain）执行流程是怎样的？', 'Spring Cloud Gateway 基于 Spring 5、Project Reactor 和 Netty 开发，采用响应式非阻塞异步架构。核心由三大要素构成：Route（路由定义：ID、目标 URI、断言集合、过滤器集合）、Predicate（断言：匹配 HTTP 请求的 Path、Method、Header 等条件）、Filter（过滤器：对请求和响应进行拦截和改写）。执行流程：请求到达 ➔ 路由匹配 HandlerMapping ➔ 构建责任链式 WebFilter 链 ➔ 依次执行 Pre 过滤器 ➔ Netty 发送代理请求 ➔ 依次执行 Post 过滤器 ➔ 返回客户端响应。', 'SpringCloudGateway,网关,过滤器链,断言,Predicate,Route,Netty,响应式', 'Spring与微服务', 1, 'it-124', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (125, 'MySQL InnoDB 存储引擎与 MyISAM 引擎的核心区别是什么？', '核心区别：1. 事务支持：InnoDB 支持 ACID 事务，具备回滚机制；MyISAM 不支持事务；2. 锁粒度：InnoDB 支持行级锁（行锁配合索引）和表锁，并发写入能力强；MyISAM 仅支持表锁，写操作会阻塞所有读写；3. 灾难恢复：InnoDB 拥有 redo log 与 undo log，具备崩溃安全恢复（Crash-Safe）；MyISAM 宕机易损坏数据表；4. 外键支持：InnoDB 原生支持外键关联约束；MyISAM 不支持；5. 存储方式：InnoDB 是聚簇索引（数据和主键索引存放在同一个 ibd 文件）；MyISAM 是非聚簇索引（索引文件 MYI 与数据文件 MYD 分开存储）。', 'InnoDB,MyISAM,存储引擎,行级锁,表锁,事务支持,崩溃恢复,聚簇索引', 'MySQL与数据存储', 1, 'it-125', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (126, 'MySQL 索引为什么选择 B+ 树而不是 B 树、哈希表或红黑树？', '1. 对比哈希表：哈希表等值查询 O(1) 极快，但无法支持范围查询（`BETWEEN`、`>`、`<`）和排序（`ORDER BY`）；2. 对比二叉树/红黑树：二叉树每个节点只有两个子节点，树的高度极深，高数据量下磁盘 I/O 次数巨大；3. 对比 B 树：B 树所有节点都存储键和数据行，导致每个磁盘页能容纳的索引键数量较少，树的高度增加。而 B+ 树的非叶子节点只存储索引键不存数据，单页可容纳千余个索引项，3 层 B+ 树即可索引千万级数据；且叶子节点包含所有数据并通过双向链表相连，极大提升了范围扫描与全表遍历性能。', 'B+树,B树,索引原理,二叉树,红黑树,哈希索引,范围查询,磁盘IO', 'MySQL与数据存储', 1, 'it-126', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (127, '什么是聚簇索引与非聚簇索引（二级索引）？什么是回表查询？', '1. 聚簇索引（Clustered Index）：InnoDB 中按照主键构建的 B+ 树，其叶子节点存储了完整的行记录数据（索引与数据即为一体），一张表有且仅有一个聚簇索引；2. 二级索引（Secondary Index）：由普通字段建立的索引，其叶子节点只存储该字段值及对应的主键值；3. 回表查询：当通过二级索引查询时，先在二级索引树查到主键 ID，再拿主键 ID 回到聚簇索引树查找整行数据，多经历一次树查询即为“回表”。可通过“覆盖索引”消除回表以优化性能。', '聚簇索引,非聚簇索引,二级索引,回表查询,覆盖索引,主键索引', 'MySQL与数据存储', 1, 'it-127', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (128, '什么是覆盖索引与最左前缀原则？如何避免常见的索引失效？', '覆盖索引是指查询语句所需要的字段列全部存在于所使用的索引树中，无需回表。最左前缀原则指在联合索引 `(a, b, c)` 中，查询条件必须从最左列开始连续匹配，否则无法使用后续索引。常见索引失效场景：1. 在索引列上做函数运算、数学计算或隐式类型转换（如数字与字符串未加引号）；2. 使用非最左前缀或跳过联合索引前置列；3. 以通配符 `%` 开头的 LIKE 模糊查询（如 `%keyword`）；4. OR 关联的字段中有一方未建立索引；5. 不等于（`!=` 或 `<>`）及特定 `NOT IN` 导致的全表扫描更优选择。', '覆盖索引,最左前缀原则,索引失效,联合索引,隐式转换,like模糊查询', 'MySQL与数据存储', 1, 'it-128', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (129, 'MySQL 事务的 ACID 特性分别是什么？底层是如何保证的？', 'ACID 特性：1. 原子性（Atomicity）：事务内操作要么全成功要么全回滚，由 `undo log`（回滚日志）保证；2. 一致性（Consistency）：数据从一个合法状态转变到另一个合法状态，是事务追求的最终目标；3. 隔离性（Isolation）：多个并发事务相互独立隔离，由锁机制（Record Lock, Gap Lock）与 `MVCC` 多版本并发控制保证；4. 持久性（Durability）：事务一旦提交其变更永久保存在磁盘，由 `redo log`（重做日志）与 WAL（Write-Ahead Logging 先写日志后写盘）机制保证。', 'MySQL,MySQL事务,事务,ACID,ACID特性,特性,原子性,一致性,隔离性,持久性,redolog,undolog,WAL', 'MySQL与数据存储', 1, 'it-129', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (130, 'MySQL 事务的四种隔离级别是什么？分别解决了什么并发读问题？', 'SQL 标准定义的四种隔离级别：1. 读未提交（Read Uncommitted）：最低级别，会产生脏读（Dirty Read）、不可重复读、幻读；2. 读已提交（Read Committed）：解决脏读，每次 SELECT 读取生成新的 ReadView，仍存在不可重复读和幻读（Oracle 默认）；3. 可重复读（Repeatable Read）：解决脏读和不可重复读，事务内首次 SELECT 生成 ReadView 并贯穿始终，配合 Next-Key Lock 基本解决幻读（MySQL InnoDB 默认）；4. 串行化（Serializable）：强制事务串行执行，完全解决所有并发问题，但并发性能极低。', 'MySQL,MySQL事务,事务,事务隔离级别,隔离级别,四种隔离级别,读未提交,读已提交,可重复读,串行化,脏读,幻读', 'MySQL与数据存储', 1, 'it-130', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (131, '什么是 MVCC（多版本并发控制）？ReadView 是如何实现快照读的？', 'MVCC 是在不加锁的情况下提升数据库读写并发性能的机制。实现依赖于每行记录的 3 个隐藏字段（DB_TRX_ID 事务ID、DB_ROLL_PTR 回滚指针、DB_ROW_ID）、undo log 版本链以及 ReadView（读视图）。ReadView 包含当前活跃未提交事务 ID 列表（m_ids）、最小活跃事务 ID（min_trx_id）、最大已分配事务 ID（max_trx_id）及创建者事务 ID（creator_trx_id）。事务读取时沿 undo log 版本链向前比对：若版本的 trx_id 小于 min_trx_id 或等于 creator_trx_id 则可见；若大于等于 max_trx_id 或在 m_ids 中则不可见，依此找到该事务可见的历史版本。', 'MVCC,多版本并发控制,ReadView,快照读,undolog版本链,隐藏字段,trx_id', 'MySQL与数据存储', 1, 'it-131', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (132, 'MySQL 中的当前读与快照读有什么区别？Next-Key Lock 是如何解决幻读的？', '1. 快照读（Snapshot Read）：普通的 `SELECT` 查询，通过 MVCC 读取记录的历史快照版本，不加锁，非阻塞；2. 当前读（Current Read）：如 `SELECT ... FOR UPDATE`、`LOCK IN SHARE MODE`、`UPDATE`、`DELETE`，读取的是记录的最新版本，并且必须对读取的记录加锁。InnoDB 在可重复读级别下，当前读通过 `Next-Key Lock`（行记录锁 Record Lock + 间隙锁 Gap Lock）将记录本身及其两侧的开区间间隙锁死，阻止其他事务向间隙内插入新数据（INSERT 阻塞），从而彻底杜绝了当前读场景下的幻读问题。', '当前读,快照读,NextKeyLock,间隙锁,GapLock,行锁,解决幻读', 'MySQL与数据存储', 1, 'it-132', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (133, 'MySQL 慢 SQL 常见排查定位方法与 EXPLAIN 执行计划关键指标分析', '排查流程：1. 开启慢查询日志（`slow_query_log=ON`, 设定 `long_query_time` 阈值）；2. 借助 `mysqldumpslow` 或监控工具汇总分析高频慢查询；3. 使用 `EXPLAIN` 分析执行计划。核心指标：- `type`：访问类型，性能由好到差为 system > const > eq_ref > ref > range > index > ALL（ALL为全表扫描，原则上必须优化至 range/ref 以上）；- `key`：实际使用的索引；- `rows`：预估扫描行数；- `Extra`：包含 `Using filesort`（文件排序）或 `Using temporary`（使用临时表）时需重点优化，出现 `Using index` 表示覆盖索引。', '慢SQL,EXPLAIN,执行计划,type,Extra,慢查询日志,索引优化,全表扫描', 'MySQL与数据存储', 1, 'it-133', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (134, 'MySQL 主从复制的底层工作原理是什么？如何解决主从复制延迟问题？', '主从复制分为 3 步：1. 主库在事务提交时将数据变更记录写入 Binary Log（binlog）；2. 从库通过 I/O 线程连接主库，请求并接收 binlog 内容写入本地 Relay Log（中继日志）；3. 从库 SQL 线程读取 Relay Log 并回放 SQL 实现数据同步。binlog 常见格式有 Statement、Row（推荐，记录行变动，无函数不确定性）和 Mixed。解决主从延迟：1. 开启从库多线程并行复制（MTS）；2. 从库升级 SSD 硬件；3. 核心强一致性业务（如支付订单刚写入后的立即查询）强制路由走主库查询。', 'MySQL,主从复制,主从同步,从库延迟,主从延迟,复制原理,binlog,RelayLog,多线程复制,Row格式', 'MySQL与数据存储', 1, 'it-134', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (135, '数据库分库分表的拆分维度有哪些？ShardingSphere 核心架构与原理是什么？', '拆分维度：1. 垂直拆分：垂直分库（按微服务业务领域拆分库，如用户库、课程库、订单库）、垂直分表（大表冷热字段分离，将大文本列拆出）；2. 水平拆分：水平分表/分库（单表数据量过亿，按 Hash 取模、时间范围或租户 ID 将行数据打散到多个物理库表）。Apache ShardingSphere 是开源分布式数据库中间件生态，核心包含 SQL 解析、路由计算（按分片键确定物理节点）、SQL 改写（改写逻辑表名为真实物理表名）、执行器并发执行与结果集合并（排序、分页、聚合函数归并）。', '分库分表,ShardingSphere,水平拆分,垂直拆分,分片键,路由改写,读写分离', 'MySQL与数据存储', 1, 'it-135', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (136, '乐观锁与悲观锁在数据库中的实现方式与应用场景是什么？', '1. 悲观锁（Pessimistic Lock）：假定并发冲突概率极高，每次访问数据前都显式加排他锁。数据库层面通过 `SELECT ... FOR UPDATE` 实现，其他事务试图修改或加锁时将被挂起阻塞，适用于写多读少、强一致性要求的金融账务扣款场景；2. 乐观锁（Optimistic Lock）：假定并发冲突极低，操作数据时不加锁，仅在更新提交时核验版本。常用方式是在表中增加 `version` 整数列，更新时执行 `UPDATE table SET val = ?, version = version + 1 WHERE id = ? AND version = old_version`，若受影响行数为 0 则触发重试或失败，适用于读多写少的高并发电商秒杀扣库存场景。', '乐观锁,悲观锁,version版本号,FORUPDATE,CAS,并发冲突,排他锁', 'MySQL与数据存储', 1, 'it-136', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (137, 'Redis 为什么速度这么快？单线程模型为什么能支撑高并发？', '核心原因：1. 内存存储：数据全部存储在内存中，内存读写速度（纳秒级）是机械/固态磁盘（微秒/毫秒级）的数千倍；2. 高效数据结构：专门优化底层编码（如 SDS 简单动态字符串、跳表 SkipList、压缩列表 ListPack）；3. 单线程无锁开销：核心命令执行由单主线程完成，彻底消除了多线程上下文切换、CPU 核心争抢及复杂的加锁解锁开销；4. I/O 多路复用：基于 Linux epoll 的非阻塞 I/O 事件驱动模型，单个线程即可高效并发监听数万个客户端网络连接。注：Redis 6.0 引入了多线程网络 I/O 解析，但命令执行核心依然保持单线程。', 'Redis,速度快,单线程,单线程模型,为什么快,多路复用,epoll,内存存储,高并发原因', 'Redis与高性能缓存', 1, 'it-137', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (138, 'Redis 五种常用基础数据结构底层编码实现是怎样的？', '1. String：底层为 SDS（Simple Dynamic String），记录长度 len 与空闲空间，O(1) 获取长度且二进制安全；2. List：双向链表或 QuickList（压缩列表 + 双向链表组合）；3. Hash：元素少时采用 ZipList/ListPack，元素多或单个值长时转为 HashTable 字典；4. Set：整数集合 IntSet（全数字且数量少）或 HashTable（Value 为 null 的字典）；5. ZSet（有序集合）：元素少时使用 ZipList，元素多时使用【跳表 SkipList + 字典 HashTable】联合实现，兼顾 O(log n) 范围查询与 O(1) 分值查询。', 'Redis,数据结构,底层实现,基础数据结构,底层编码,SDS,跳表,QuickList,ZipList,HashTable', 'Redis与高性能缓存', 1, 'it-138', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (139, '什么是缓存穿透、缓存击穿、缓存雪崩？各自的最佳解决方案是什么？', '1. 缓存穿透：大量请求查询数据库中根本不存在的数据（如非法 ID），请求直穿底层 DB 导致崩溃。方案：接口参数合法性校验、缓存空对象（设置短 TTL 1~5分钟）、布隆过滤器（Bloom Filter）前置快速拦截；2. 缓存击穿：单个热点 Key（高并发访问）在某一瞬间过期失效，海量请求同时并发穿透查 DB 重建缓存。方案：互斥排他锁（setnx）保证单线程重建、热点数据设置逻辑永不过期并在后台异步刷新；3. 缓存雪崩：大量不同 Key 在同一时间集中过期，或 Redis 服务节点宕机导致所有请求涌入 DB。方案：过期时间加上随机抖动偏移量（如 TTL + Random(1~5min)）、搭建 Redis 主从哨兵高可用集群、配置降级与限流。', '缓存穿透,缓存击穿,缓存雪崩,布隆过滤器,互斥锁,随机过期时间,缓存高可用', 'Redis与高性能缓存', 1, 'it-139', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (140, 'Redis 分布式锁是如何实现的？为什么必须配合 Lua 脚本保证原子性？', '标准实现：`SET lock_key unique_value NX PX 30000`。其中 `NX` 保证只有 key 不存在时才能设置成功（互斥加锁），`PX` 设置过期时间毫秒数防死锁。释放锁时必须核对 `unique_value` 与当前客户端生成的 UUID 是否一致，防止 A 客户端业务超时后释放了 B 客户端新获得的锁。比对 value 与删除 key 是两步操作，必须通过 Lua 脚本执行（`if redis.call("get", KEYS[1]) == ARGV[1] then return redis.call("del", KEYS[1]) else return 0 end`），利用 Redis 单线程执行 Lua 脚本的不可中断性确保释放锁的原子性。针对锁续期需求可引入 Redisson 看门狗（Watchdog）机制。', '分布式锁,Redis锁,Lua脚本,原子性,SETNX,看门狗,Redisson,防死锁', 'Redis与高性能缓存', 1, 'it-140', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (141, 'Redis Redlock（红锁）算法的原理是什么？为什么业界存在争议？', 'Redlock 是 Redis 官方提出的在多独立主节点集群下的分布式锁算法。原理：客户端依次向 N 个（通常为 5 个）互相独立的 Redis 实例请求加锁；当且仅当在大多数（N/2 + 1 = 3个）实例上加锁成功，且获取锁耗费的总时间小于锁有效时间时，才认为加锁成功。争议：分布式权威 Martin Kleppmann 曾指出，Redlock 高度依赖物理系统的系统时钟（NTP 时钟跳跃会导致锁过早失效），且无法解决长垃圾回收（STW GC）或网络分区导致的并发竞态安全问题；若对分布式一致性要求极高，更推荐基于强一致性共识协议的 ZooKeeper 或 etcd。', 'Redlock,红锁,分布式锁算法,时钟漂移,Martin争论,etcd对比,高可用锁', 'Redis与高性能缓存', 1, 'it-141', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (142, 'Redis 数据持久化机制：RDB 与 AOF 的原理、优缺点及混合持久化', '1. RDB（快照）：定时将内存完整数据集以二进制压缩格式写入 dump.rdb 文件。通过 `bgsave` fork 出子进程进行写时复制（COW）。优点：恢复大数据集极快，文件紧凑；缺点：非实时，宕机丢失最后一次快照后的所有数据；2. AOF（追加日志）：将每个写命令记录到 appendonly.aof。支持 everysec（每秒刷盘，推荐）、always 与 no。优点：数据安全度高；缺点：文件体积大，恢复慢；3. 混合持久化（4.0+）：AOF 重写时将前半段快照保存为 RDB 格式，后半段增量指令以 AOF 追加，兼具 RDB 的极速恢复与 AOF 的低丢数据优势。', 'RDB,AOF,持久化,混合持久化,写时复制,COW,bgsave,appendfsync', 'Redis与高性能缓存', 1, 'it-142', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (143, 'Redis 内存淘汰策略（Eviction Policies）有哪些？LRU 与 LFU 有何区别？', '当内存达到 `maxmemory` 上限时触发淘汰。包含 8 种策略：1. noeviction（默认）：拒绝写入并报错；2. volatile-lru：从设置了过期时间的 key 中淘汰最近最少使用；3. allkeys-lru：从所有 key 中淘汰最近最少使用；4. volatile-lfu：淘汰最不经常使用（频次最低）；5. allkeys-lfu：从所有 key 中淘汰最不经常使用；6. volatile-random / allkeys-random：随机淘汰；7. volatile-ttl：淘汰剩余 TTL 最短的 key。区别：LRU（Least Recently Used）关注最后一次访问时间；LFU（Least Frequently Used）关注访问频率计数（利用半衰期降权），更能真实反映热点数据的持久价值。', '内存淘汰策略,LRU,LFU,maxmemory,淘汰算法,noeviction,热点数据', 'Redis与高性能缓存', 1, 'it-143', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (144, 'Redis 过期键删除策略有哪些？惰性删除与定期删除如何协同？', 'Redis 采用【惰性删除 + 定期删除】协同机制：1. 惰性删除（Lazy Free）：当客户端访问某个 key 时，Redis 检查其是否过期，若过期则立即删除并返回 nil。优点：CPU 友好，不浪费算力去轮询；缺点：若大量过期 key 永远不再被访问，会长期白白占用内存；2. 定期删除（Active Expire）：Redis 默认每秒运行 10 次后台定时任务（serverCron），随机抽取一定数量（如20个）带 TTL 的 key 进行检查，若过期比例超过 25% 则继续循环清理。两者结合在 CPU 开销与内存回收率之间取得了最佳平衡。', '过期删除,惰性删除,定期删除,TTL过期,内存回收,serverCron', 'Redis与高性能缓存', 1, 'it-144', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (145, 'Redis 主从复制、哨兵模式（Sentinel）与集群模式（Cluster）的区别与选型', '1. 主从复制（Replication）：单主多从，主写从读，实现读写分离扩展读 QPS，但主节点宕机无法自动故障转移；2. 哨兵模式（Sentinel）：由独立哨兵集群对主从节点进行心跳监控、自动选主与故障转移（Failover），通知客户端新主地址，解决了高可用问题，但单个 Master 仍然受限于单机内存与写性能瓶颈；3. 集群模式（Cluster）：分布式分片架构，支持多主多从，通过 16384 个哈希槽将写请求水平扩展到多台物理机器，支持海量数据存储与超大规模高并发写，是大规模企业级首选架构。', 'Redis,主从复制,哨兵模式,哨兵,Sentinel,集群,Cluster,集群模式,选型对比,高可用', 'Redis与高性能缓存', 1, 'it-145', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (146, 'Redis Cluster 集群的哈希槽（Hash Slot）机制与数据分片原理', 'Redis Cluster 预置了固定数量的 `16384` 个哈希槽（Slots：0 ~ 16383）。每个 Master 节点负责管理其中一部分连续或离散的槽位。当执行键值操作时，客户端或服务端通过 CRC16 校验和对 key 计算哈希值并对 16384 取模：`slot = CRC16(key) & 16383`。若 key 包含 `{hash_tag}`，则仅对花括号内的字符串进行哈希，确保相关联的多个 key 映射到同一个哈希槽和节点。若客户端请求的 key 不在当前节点负责的槽位，节点返回 `-MOVED slot ip:port` 重定向指引客户端跳转访问正确节点。', 'Redis,Cluster,哈希槽,HashSlot,slot,16384,CRC16,集群分片,重定向', 'Redis与高性能缓存', 1, 'it-146', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (147, '如何保证 Redis 缓存与 MySQL 数据库的双写一致性？（Cache Aside Pattern）', '最经典的工业界模式为 Cache Aside Pattern（旁路缓存模式）：1. 读取：先查缓存，命中则返回；未命中则查数据库，将结果写入缓存并返回；2. 更新：先更新数据库，再删除缓存（而非直接更新缓存）。为什么删除而非更新：避免高并发并发写导致缓存脏数据覆盖，且删除是惰性计算更为节省。为什么先更 DB 再删 Cache：产生不一致概率极低。若需要极限强一致性，可结合【延迟双删】（先删缓存 ➔ 改库 ➔ 休眠几百毫秒 ➔ 再次删缓存）或基于阿里开源 Canal 监听 MySQL binlog 异步消费消息重试删除缓存。', 'Redis,MySQL,双写一致性,双写一致,缓存双写,双写,一致性,CacheAside,旁路缓存,延迟双删,Canal', 'Redis与高性能缓存', 1, 'it-147', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (148, 'Redis 常见性能瓶颈分析：BigKey（大Key）与 HotKey（热Key）的排查及解决方案', '1. BigKey（体积或元素量超大）：危害在于单线程阻塞、网络带宽耗尽及删除时引发 STW。排查：`redis-cli --bigkeys` 或分析 RDB。解决：拆分大 Key、禁用全量读取操作（如禁 keys * 改用 scan，hgetall 改用 hscan）、异步非阻塞删除（`UNLINK` 命令代替 `DEL`）；2. HotKey（瞬间访问 QPS 极高）：危害在于瞬时流量打爆单个 Redis 分片网卡。排查：`redis-cli --hotkeys` 或利用客户端代理层统计。解决：在应用本地添加多级缓存（Caffeine / Guava Cache）、将热 Key 加上随机后缀分散存储到多个 Redis 分片节点。', 'BigKey,HotKey,大Key,热Key,UNLINK,Caffeine,本地缓存,Redis调优', 'Redis与高性能缓存', 1, 'it-148', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (149, '消息队列（MQ）的核心应用场景有哪些？各自解决什么业务痛点？', '三大核心价值场景：1. 异步解耦：将耗时较长、非核心链路从主流程中剥离（如用户注册成功后异步发送短信通知、赠送新人礼包，主业务立即返回成功响应，系统间不再直接依赖 API）；2. 流量削峰填谷：在电商大促秒杀或技术活动抢购场景下，瞬时并发请求可能超出数据库承载极限，消息队列作为蓄水池暂存海量请求，后台消费者按自身处理能力平稳匀速拉取消费；3. 系统广播与事件驱动：一个业务事件（如订单支付完成）触发多个下游子系统（库存扣减、发票生成、风控积分）并发监听处理。', '消息队列,应用场景,异步处理,系统解耦,削峰填谷,高并发秒杀,事件驱动', '消息队列与中间件', 1, 'it-149', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (150, '主流消息队列选型对比：Kafka、RocketMQ 与 RabbitMQ 优缺点与适用场景', '1. Kafka：基于 Scala/Java，百万级 TPS 吞吐量极致，支持分区并行、零拷贝与页面缓存，生态成熟，非常适合大数据日志收集、指标监控与流式实时计算；2. RocketMQ：阿里开源顶级项目，支持几十万 TPS，采用 Java 原生编写，功能特性极为丰富（支持严格顺序消息、定时延时消息、分布式事务消息、亿级消息堆积），是国内大型电商与互联网核心业务系统首选；3. RabbitMQ：基于 Erlang 语言，万级 TPS，基于 AMQP 协议，支持灵活丰富的交换机（Exchange）路由拓扑，管理后台直观友好，时延极低（微秒级），适合中小企业中敏捷快速业务开发。', 'MQ选型,Kafka,RocketMQ,RabbitMQ,对比,吞吐量,延迟队列,事务消息', '消息队列与中间件', 1, 'it-150', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (151, 'Kafka 为什么具有极高的吞吐量？零拷贝（Zero-Copy）机制是怎样的？', '高吞吐核心架构支撑：1. 顺序写磁盘：Kafka 采用追加日志（Append-only log）方式写入文件，顺序写速度接近甚至超过内存随机读写；2. PageCache 页面缓存：充分利用 Linux 操作系统缓存，尽可能在内存中完成读写，避免频繁下发磁盘 I/O；3. 零拷贝技术（Zero-Copy）：消费数据时采用 Linux 系统调用 `sendfile`，数据直接从 OS PageCache 传输到网卡缓冲区，完全跳过用户态内存拷贝与 CPU 上下文切换；4. 分区并发（Partition）：一个 Topic 拆分多个 Partition，各 Broker 节点独立并发读写；5. 批量压缩（Batch Compression）：多条小消息打包合并压缩发送。', 'Kafka,高吞吐,高吞吐量,零拷贝,ZeroCopy,sendfile,PageCache,顺序写盘,吞吐量', '消息队列与中间件', 1, 'it-151', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (152, 'Kafka 的消息分区（Partition）与消费者组（Consumer Group）机制是怎样的？', '1. 分区（Partition）：Topic 在物理上的并行切片，是 Kafka 并发与横向扩容的基本单元，单个 Partition 内消息严格保序且具备单调递增的 Offset 偏移量；2. 消费者组（Consumer Group）：实现发布-订阅与点对点两种模型的关键。同一消费者组内的多个消费者共同协作消费该 Topic 的所有分区，但【一个 Partition 同时只能被同一个 Group 内的某一个 Consumer 消费】；不同 Group 之间互不干扰。当消费者上线或宕机时，会触发 Rebalance（再均衡）重新分配分区所有权。', 'Partition,分区,消费者组,ConsumerGroup,Rebalance,Offset,负载均衡', '消息队列与中间件', 1, 'it-152', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (153, '消息队列如何保证消息的绝对顺序性（顺序消费）？', '保证顺序必须做到“生产顺序 ➔ 队列顺序 ➔ 消费顺序”三环节闭环：1. 生产端：将需要保序的消息指定同一个业务 Key（如同一笔订单的创建、支付、发货），确保消息通过 Hash 算法路由写入同一个 Partition 或 MessageQueue；2. 存储端：单个 Partition / MessageQueue 内部天然是有序追加写入的单向队列；3. 消费端：单个 Partition 只能由单个消费线程单线程拉取消费，消费端禁止多线程异步乱序处理同一 Partition 的消息。若需要并行，可在内存中按业务 Key 再次哈希分发给不同的内部工作队列执行。', '消息队列,顺序消费,顺序消息,消息顺序,保序,局部有序,分区有序,MessageQueue', '消息队列与中间件', 1, 'it-153', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (154, '消息队列如何保证消息不丢失？高可靠投递与持久化机制是怎样的？', '必须防范三处丢失点：1. 生产端防丢：采用同步发送或带回调的异步发送，配置 ACK 参数（Kafka 设置 `acks=all` 或 `-1`），要求主副本与所有 ISR 同步副本全部确认写入后才算成功，否则自动重试；2. Broker 端防丢：开启持久化刷盘机制，Kafka 配置高可靠多副本机制（`min.insync.replicas >= 2`），RocketMQ 采用同步双写（SYNC_MASTER）；3. 消费端防丢：关闭自动提交 Offset（如 Kafka 设置 `enable.auto.commit=false`），待业务逻辑真正执行成功并且入库后再显式手动提交 ACK / Offset。', '消息队列,消息丢失,防止丢失,防丢失,消息不丢失,高可靠投递,高可靠,手动ACK,acks=all', '消息队列与中间件', 1, 'it-154', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (155, '消息队列如何处理消息重复消费？消费幂等性如何设计？', '由于网络闪断、超时重试或 Rebalance，消息重复投递是分布式系统的常态，因此消费端必须具备【幂等性（Idempotency）】。常用方案：1. 唯一业务流水号（如订单号 + 业务类型），消费前先查数据库或 Redis 判断该记录是否已处理过；2. 数据库唯一键约束（Unique Key）：利用主键冲突或唯一索引直接防御并发插入重复记录；3. 状态机防重：在订单状态流转中采用前置条件控制（如 `UPDATE t_order SET status=2 WHERE id=? AND status=1`），状态已跃迁则受影响行数为 0，天然防重；4. 分布式锁防并发消费。', '重复消费,消费幂等性,幂等设计,唯一业务号,唯一键,状态机防重,防重复', '消息队列与中间件', 1, 'it-155', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (156, '如何处理消息队列中的消息积压（Backlog）问题？排查思路与应急扩容方案', '积压根本原因是：生产速度长期远高于消费速度，或下游消费者发生慢 SQL、死锁、依赖下游服务超时崩溃。应急处理步骤：1. 先紧急修复消费端 Bug 或调整下游限流阈值恢复消费能力；2. 紧急扩容方案：临时停掉原消费者进程，建立一个临时的中转 Topic 并创建数十倍于原分区的临时 Partition，编写临时分发消费者仅做快速中转转发，将积压消息瞬间平摊到几十个新分区中，再起几十倍的新消费者集群并发快速消化；3. 长期治理：优化消费端耗时逻辑、引入批量消费、提升消费线程数。', '消息队列,消息积压,积压,堆积,消息堆积,消费慢,应急扩容,Backlog,消息治理', '消息队列与中间件', 1, 'it-156', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (157, 'RocketMQ 事务消息（半消息机制）的执行原理是怎样的？', '基于两阶段提交思想：1. 发送方首先向 RocketMQ 发送一条【半消息（Half Message）】，该消息对消费者不可见；2. 半消息发送成功后，发送方执行本地数据库事务（如本地订单落库）；3. 根据本地事务执行结果，发送方发送二次确认指令：提交（Commit，使消息对下游可见）或回滚（Rollback，丢弃该消息）；4. 若网络异常二次确认丢失，RocketMQ 服务端会发起定时【消息回查（Check）】，调用发送方提供的回查接口检查本地事务真实状态，并依据结果最终决定提交或回滚，实现跨系统的最终一致性。', 'RocketMQ,事务消息,半消息,HalfMessage,两阶段提交,消息回查,最终一致性', '消息队列与中间件', 1, 'it-157', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (158, 'RabbitMQ 延时队列的实现原理是怎样的？（TTL + 死信交换机 DLX）', '原生 RabbitMQ 常用【TTL 消息存活时间 + DLX 死信交换机】实现延时：1. 创建一个正常业务队列，不设置消费者，为其配置消息过期时间（`x-message-ttl`），并绑定死信交换机（`x-dead-letter-exchange`）与死信 RoutingKey；2. 生产者向该队列发送待延时消息；3. 当消息在队列中等待超时未被消费，自动变为死信（Dead Letter）；4. RabbitMQ 自动将死信路由投递至绑定的死信交换机，并进入延时目标队列由实际工作消费者处理，从而达到定时延时触发效果；亦可使用官方 `rabbitmq-delayed-message-exchange` 插件实现。', '延时队列,RabbitMQ,死信队列,DLX,TTL,死信交换机,定时任务', '消息队列与中间件', 1, 'it-158', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
