VALUES (166, 'React Hooks 核心原理是什么？useState 与 useEffect 的闭包陷阱如何规避？', 'Hooks 原理：在函数组件对应的 Fiber 节点上维护了一条单向链表 `memoizedState`，每次执行 Hook（如 useState/useEffect）时按固定调用顺序遍历链表获取对应状态，这也是“为什么 Hooks 绝不能写在 if 条件分支或循环内部”的根本原因。闭包陷阱产生原因：useEffect 或事件回调中捕获了旧渲染周期内的快照状态变量。规避方案：1. 规范声明依赖项数组（deps），不要遗漏依赖；2. 使用函数式更新 `setCount(prev => prev + 1)`；3. 结合 `useRef` 保存跨生命周期最新的可变引用。', 'ReactHooks,useState,useEffect,闭包陷阱,依赖项数组,useRef,Fiber链表', '前端与全栈工程', 1, 'it-166', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (167, '现代前端工程化打包构建工具对比：Vite 为什么比 Webpack 启动更快？', 'Webpack 的传统冷启动原理：无论当前页面是否需要，必须递归分析整个项目的模块依赖图，将全部代码完整打包成 Bundle 后才启动开发服务器，项目越大冷启动与热更新越慢。Vite 的革命性设计：1. 开发阶段基于浏览器原生 ES 模块（Native ESM），无需打包，按需动态请求加载当前页面的模块；2. 依赖预构建使用极速的 Go 语言编写的 esbuild，编译速度比 JS 编写的 Webpack 快 10~100 倍；3. 生产构建阶段采用 Rollup，兼顾成熟插件生态与极致代码拆分优化。', 'Vite,Webpack,构建工具,NativeESM,esbuild,Rollup,热更新,冷启动,打包速度', '前端与全栈工程', 1, 'it-167', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (168, '浏览器跨域（CORS）问题产生的原因是什么？常见的解决方案有哪些？', '跨域是由于浏览器的【同源策略（Same-Origin Policy）】引起的（协议、域名、端口三者有任意一项不一致即为跨域，浏览器会拦截带有敏感响应体数据的跨源请求）。常见解决方案：1. 后端开启 CORS（跨域资源共享）：在响应头设置 `Access-Control-Allow-Origin: *`、`Access-Control-Allow-Methods` 及 `Access-Control-Allow-Credentials`；2. 开发环境反向代理：在 Vite / Webpack 开发服务器中配置 `proxy`，利用 Node.js 中间件转发请求绕过浏览器同源限制；3. 生产环境 Nginx 反向代理：将前端静态页面和后端接口部署于同一域名下的不同路径前缀（如 `/api`）统一代理。', '跨域,CORS,同源策略,反向代理,Nginx代理,ViteProxy,预检请求,Options请求', '前端与全栈工程', 1, 'it-168', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (169, 'TypeScript 中 interface 与 type 有什么区别？泛型（Generics）的作用是什么？', '1. interface 与 type 区别：- interface 专用于定义对象形状，支持多次声明合并（Declaration Merging，适合定义库接口），支持 `extends` 继承；- type 是类型别名，功能更广泛，支持联合类型（`Union`）、元组（`Tuple`）、基本类型重命名及高级映射类型，不支持声明合并；2. 泛型（Generics）：在定义函数、接口或类时不预先指定具体类型，而是将类型作为参数在使用时动态传入，在保持类型安全与完整 IDE 语法提示的同时，实现代码的高阶通用与最大化复用。', 'TypeScript,interface,type,泛型,类型别名,声明合并,类型安全,TS', '前端与全栈工程', 1, 'it-169', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
