VALUES (174, 'Docker Compose 的核心作用是什么？多容器编排与网络互通原理是怎样的？', 'Docker Compose 用于在单个宿主机上定义和运行由多个容器组成的复杂微服务应用（如一键启动 Nginx、Spring Boot、MySQL、Redis）。通过统一的 `docker-compose.yml` 声明服务依赖（`depends_on`）、端口映射、数据卷挂载及环境变量。网络原理：Docker Compose 启动时默认会为该工程创建一个独立的自定义桥接网络（Bridge Network），工程内的所有容器自动加入该网络，各容器可直接通过【服务名（Service Name）】作为域名进行内部 DNS 互相解析与通信，无需硬编码 IP。', 'DockerCompose,多容器编排,docker-compose,桥接网络,服务名通信,depends_on', '云原生与Linux运维', 1, 'it-174', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (175, 'Kubernetes（K8s）的核心架构与核心组件职责分别是什么？', 'K8s 由控制平面（Control Plane）与工作节点（Worker Node）构成：- 控制平面：1. `kube-apiserver`：集群唯一入口，暴露 REST API 供 kubectl 和内部组件交互；2. `etcd`：高可用键值存储，保存集群全量状态元数据；3. `kube-scheduler`：根据资源需求将待运行 Pod 调度到最优 Node；4. `kube-controller-manager`：运行各类控制器（如 NodeController, DeploymentController），维护集群预期状态与实际状态一致。- 工作节点：1. `kubelet`：节点核心代理，与容器运行时（CRI 如 containerd）交互管理 Pod 容器生命周期；2. `kube-proxy`：负责维护节点网络规则（iptables/IPVS），实现 Service 服务发现与负载均衡。', 'K8s,Kubernetes,核心架构,架构组件,核心组件,组件,Master节点,apiserver,etcd,kubelet', '云原生与Linux运维', 1, 'it-175', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (176, 'K8s 中 Pod、Deployment、Service 与 Ingress 的概念与关系是怎样的？', '1. Pod：K8s 中最小的部署和调度单元，包含一个或多个紧密耦合、共享网络 IP 和存储卷的容器；2. Deployment：负责管理无状态 Pod 的控制器，定义副本数量（Replicas）、声明式滚动更新（Rolling Update）与版本回滚；3. Service：Pod 的虚拟网络抽象与内网负载均衡器，由于 Pod IP 会随销毁重建而动态漂移，Service 提供固定的 ClusterIP 和 DNS 域名，利用标签选择器（Label Selector）自动路由到后端活跃的 Pod；4. Ingress：集群的外部流量七层网关入口，提供 HTTP/HTTPS 路由规则，将外部域名与请求路径转发给对应的内部 Service。', 'Pod,Deployment,Service,Ingress,K8s网络,滚动更新,服务发现,集群路由', '云原生与Linux运维', 1, 'it-176', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (177, 'K8s 中 Pod 的健康检查探针（Liveness、Readiness、Startup Probe）有何区别？', '1. Startup Probe（启动探针）：针对启动耗时较长的重型服务（如大型 Java 应用），在该探针成功之前，Liveness 和 Readiness 探针均不工作，避免服务还没启动完成就被杀死；2. Liveness Probe（存活探针）：检测容器是否处于健康运行状态，若连续失败达到阈值，kubelet 会强制杀死该容器并按重启策略重建；3. Readiness Probe（就绪探针）：检测容器是否已具备对外处理业务流量的能力，若未就绪或失败，K8s 仅将该 Pod 从对应的 Service 负载均衡端点列表（Endpoints）中剔除，暂停路由流量，但不会重启容器。', 'K8s探针,健康检查,Liveness,Readiness,Startup,存活探针,就绪探针,Endpoints', '云原生与Linux运维', 1, 'it-177', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (178, 'Linux 服务器性能排查核心四板斧：CPU、内存、磁盘 I/O、网络负载排查命令', '1. CPU 排查：`top` 查看整体负载与各进程 CPU 占用（按 P 键排序），`mpstat -P ALL 1` 查看多核使用均衡度；2. 内存排查：`free -h` 查看总物理内存、已用、缓存及 Swap 交换分区使用率；`vmstat 1` 监控虚拟内存换页与上下文切换；3. 磁盘 I/O 排查：`df -h` 检查磁盘分区容量；`iostat -xz 1` 重点观察 `%util`（磁盘忙碌百分比）与 `await`（I/O 等待时延），若 %util 接近 100% 出现高 iowait，说明遭遇云盘限速或慢 I/O 瓶颈；4. 网络排查：`netstat -nltp` 或 `ss -s` 查看连接数与端口监听；`iftop` 监控网卡瞬时流量峰值。', 'Linux性能排查,top,free,vmstat,iostat,iowait,netstat,磁盘IO,内存分析', '云原生与Linux运维', 1, 'it-178', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (179, 'Linux 常用文本处理三剑客（grep、sed、awk）核心用法与实战技巧', '1. `grep`（文本过滤）：擅长快速正则查找。如 `grep -rn "pattern" ./` 递归搜索；`grep -v` 反向排除；`grep -C 5` 显示匹配行前后上下文 5 行；2. `sed`（流编辑器）：擅长对文本做行过滤与文本替换。如 `sed -i "s/old/new/g" file.txt` 全局直接替换文件内容；`sed -n "10,20p" file.txt` 打印指定行范围；3. `awk`（文本列分析器）：擅长按列切分统计。默认以空格/制表符分列，如 `awk "{print \\$1, \\$NF}" file.txt` 打印第一列和最后一列；结合过滤与累加：`awk -F ":" "\\$3 > 1000 {sum+=\\$3} END {print sum}" /etc/passwd`。', 'grep,sed,awk,Linux三剑客,文本处理,正则搜索,文件替换,列提取', '云原生与Linux运维', 1, 'it-179', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (180, 'Nginx 常用反向代理、负载均衡策略（轮询、权重、IP Hash）与动静分离配置', '1. 反向代理：通过 `location /api/ { proxy_pass http://backend_upstream; }` 将客户端请求隐藏透明地转发至后端集群；2. 负载均衡策略（在 upstream 块中配置）：- 轮询（Round Robin，默认）：按请求时间依次分配；- 权重（`weight=n`）：按权重比例调度，性能高的机器分配更多连接；- IP Hash（`ip_hash;`）：基于客户端 IP 计算哈希路由到固定服务器，用于解决 Session 绑定；- 最少连接数（`least_conn;`）：优先调度给活跃连接最少的后端；3. 动静分离：将静态 HTML/CSS/JS/图片资源直接由 Nginx 本地读取（配合 sendfile 与 expires 缓存），动态接口请求反向代理到微服务网关。', 'Nginx,反向代理,负载均衡,upstream,轮询,权重,ip_hash,动静分离,proxy_pass', '云原生与Linux运维', 1, 'it-180', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (181, 'Nginx 高性能优化关键配置参数解析（Worker、连接数、sendfile、gzip）', '核心调优配置：1. `worker_processes auto;`：让 Nginx 启动的工作进程数与 CPU 核心数自动保持一致；2. `worker_cpu_affinity auto;`：绑定 worker 进程到具体的 CPU 核心，减少 CPU 切换开销；3. `worker_connections 65535;`：单个 worker 进程允许的最大并发连接数；4. `sendfile on;` 与 `tcp_nopush on;`：开启内核零拷贝传输文件，极大降低磁盘读取与网络传输上下文切换；5. `keepalive_timeout 65;`：长连接超时时间；6. `gzip on;`：开启 Gzip 压缩（配置 `gzip_types` 与 `gzip_comp_level 5`），文本资源传输体积通常可压缩 70% 以上。', 'Nginx,高性能,调优,高性能调优,核心配置,优化配置,worker_processes,sendfile,gzip', '云原生与Linux运维', 1, 'it-181', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (182, 'CI/CD 持续集成与持续部署流水线的核心阶段与自动化实践是怎样的？', 'CI/CD 实现了从代码推送到线上运行的自动化流水线闭环：1. 持续集成（CI）：代码提交（Push / PR）触发自动化代码静态检查（SonarQube/Checkstyle）、单元测试执行并生成测试覆盖率报告、编译打包（Maven package / npm run build），若任意一步报错立即打断流水线并邮件通知提交者；2. 持续交付/部署（CD）：通过 Dockerfile 自动化构建服务镜像并推送到容器镜像仓库（Harbor/阿里云ACR），接着通过 Helm / kubectl / SSH 触发目标环境（测试/预发/生产）的滚动更新与冒烟自动化验证，实现低风险、高频次、标准化的敏捷交付。', 'CICD,持续集成,持续部署,GitHubActions,Jenkins,自动化流水线,自动化构建,滚动发布', '云原生与Linux运维', 1, 'it-182', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (183, 'TCP 三次握手与四次挥手的详细流程是怎样的？为什么挥手需要等待 2MSL？', '1. 三次握手：客户端发送 SYN(seq=x) ➔ 服务端收到并回复 SYN+ACK(seq=y, ack=x+1) ➔ 客户端回复 ACK(ack=y+1)，双方确认彼此收发能力正常并同步初始序列号；2. 四次挥手：客户端发送 FIN ➔ 服务端回复 ACK（此时进入半关闭状态，服务端可能仍有数据待发送） ➔ 服务端发送完毕后发送 FIN ➔ 客户端回复 ACK 并进入 TIME_WAIT 状态；3. 为什么等待 2MSL（Maximum Segment Lifetime，报文最大生存时间）：① 保证客户端发送的最后一个 ACK 报文能够顺利到达服务端，若丢包服务端重发 FIN，客户端在 2MSL 内可重新发送 ACK；② 确保本次连接产生的所有网络残留报文在网络中彻底消亡，防止“迷途报文”干扰后续新建立的连接。', 'TCP三次握手,四次挥手,2MSL,TIME_WAIT,SYN,ACK,FIN,序列号,网络协议', '计算机网络与安全', 1, 'it-183', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (184, 'TCP 与 UDP 协议的核心区别是什么？各自适用于哪些业务场景？', '1. 连接性：TCP 是面向连接的可靠流式传输协议；UDP 是无连接的面向报文传输协议；2. 可靠性：TCP 通过确认应答、超时重传、流量控制和拥塞控制保证数据无差错、不丢失、不重复且按序到达；UDP 不保证可靠交付，只管尽最大努力发送；3. 开销与速度：TCP 首部最小 20 字节，传输开销大速度相对慢；UDP 首部仅 8 字节，开销极小且速度极快；4. 适用场景：TCP 适用于对数据准确性要求极高的场景（HTTP/HTTPS 网页、文件传输 FTP、邮件 SMTP、金融交易）；UDP 适用于对实时性要求高但容忍少量丢包的场景（音视频通话、实时流媒体、在线竞技游戏、DNS 解析）。', 'TCP,UDP,协议区别,网络传输,适用场景,实时通信,三次握手', '计算机网络与安全', 1, 'it-184', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (185, 'TCP 是如何实现可靠传输的？（确认应答、超时重传、流量控制、拥塞控制）', '五大核心保障机制：1. 序列号与确认应答（ACK）：发送方为每个字节分配序列号，接收方通过 ACK 号告知下一次期望接收的字节编号；2. 超时重传（RTO）：发送方发出报文后启动定时器，超时未收到 ACK 则重新发送；3. 滑动窗口（Sliding Window）：无需每发一个包都等待确认，允许连续发送窗口大小内的数据，极大提高吞吐量；4. 流量控制（Flow Control）：接收方在 ACK 报文中携带通告窗口（rwnd）大小，防止发送方发送过快导致接收缓冲区溢出；5. 拥塞控制（Congestion Control）：通过慢启动、拥塞避免、快重传与快恢复动态调整拥塞窗口（cwnd），防止网络链路发生堵塞瘫痪。', 'TCP,可靠传输,传输可靠,超时重传,滑动窗口,流量控制,拥塞控制,ACK应答,慢启动', '计算机网络与安全', 1, 'it-185', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (186, 'HTTP 协议版本演进：HTTP 1.0、HTTP 1.1、HTTP 2.0、HTTP 3.0 的核心改进', '1. HTTP 1.0：短连接，每次请求都需要重新建立 TCP 连接；2. HTTP 1.1：引入长连接（`Keep-Alive` 默认复用 TCP）、管道化（Pipelining）、Host 请求头支持虚拟主机、Chunked 动态分块传输，但仍存在【队头阻塞（HOL）】问题；3. HTTP 2.0：基于二进制分帧层（Binary Framing），支持【多路复用（Multiplexing）】（单连接并发多个请求彻底消除 HTTP 队头阻塞）、头部压缩（HPACK 算法）、服务端推送（Server Push）；4. HTTP 3.0：彻底摒弃 TCP，改用基于 UDP 的 `QUIC` 协议，在传输层彻底解决了 TCP 的队头阻塞问题，并实现 0-RTT 极速建联与连接迁移。', 'HTTP版本,HTTP1.1,HTTP2,HTTP3,QUIC,多路复用,队头阻塞,Keep-Alive,二进制分帧', '计算机网络与安全', 1, 'it-186', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (187, 'HTTPS 的工作原理是什么？TLS/SSL 对称加密与非对称加密握手流程', 'HTTPS = HTTP + TLS/SSL 加密协议。核心流程（混合加密机制）：1. 客户端发起 `Client Hello`，发送支持的 TLS 版本和随机数 R1；2. 服务端回复 `Server Hello`，发送选定的加密套件、数字证书（包含公钥）和随机数 R2；3. 客户端验证证书合法性（通过操作系统内置 CA 根证书链校验防伪签名）；4. 验证通过后，客户端生成第三个随机数（Pre-Master Secret），用服务端的【非对称公钥】加密后发送给服务端；5. 服务端用自己的【非对称私钥】解密得到 Pre-Master Secret；6. 双方结合 R1 + R2 + Pre-Master 生成完全一致的【对称加密主密钥】；7. 后续的所有 HTTP 业务数据传输全部使用该对称密钥进行高速加密通信。', 'HTTPS,TLS,SSL握手,CA证书,数字签名,混合加密,协商密钥,对称通信', '计算机网络与安全', 1, 'it-187', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (188, 'HTTP 状态码常见分类与高频状态码解析（200, 301, 302, 400, 401, 403, 404, 500, 502, 504）', '分类：1xx 信息提示、2xx 成功、3xx 重定向、4xx 客户端错误、5xx 服务端错误。高频解析：- 200 OK：请求成功并返回内容；204 No Content：请求成功但无响应体；- 301 Moved Permanently：永久重定向（浏览器会强制缓存新 URL）；302 Found：临时重定向；304 Not Modified：协商缓存命中直接使用本地缓存；- 400 Bad Request：请求参数不合法；401 Unauthorized：未提供有效认证凭证（未登录）；403 Forbidden：已通过身份验证但没有访问权限；404 Not Found：找不到请求的资源路由；- 500 Internal Error：后端服务器代码发生未捕获异常；502 Bad Gateway：网关或 Nginx 无法连通后端微服务；504 Gateway Timeout：网关等待后端服务响应超时。', 'HTTP状态码,301,302,304,401,403,404,500,502,504,重定向,网关超时', '计算机网络与安全', 1, 'it-188', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (189, 'Session、Cookie、Token 与 JWT 认证鉴权方案的区别与选型', '1. Cookie：存储在浏览器本地的小文本（≤4KB），每次请求随请求头自动携带，易受 CSRF 攻击；2. Session：用户会话状态保存在服务端内存中，客户端仅持有 SessionID，缺点在于分布式多节点集群下需要做 Session 共享同步，水平扩容受限；3. Token：通用的令牌鉴权概念，由服务端下发并由客户端显式存放在 Storage 中在 Header 中手动携带；4. JWT（JSON Web Token）：去中心化无状态令牌，将用户 UID、角色权限及过期时间等载荷直接加密签名写入 Token 自身，服务端只需使用密钥进行验签计算即可完成身份校验，无需查询 Redis 或数据库，非常契合大规模微服务架构。', 'Session,Cookie,Token,JWT,认证鉴权,单点登录,分布式Session,区别选型', '计算机网络与安全', 1, 'it-189', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (190, 'JWT（JSON Web Token）的内部结构是怎样的？无状态 JWT 如何实现主动登出失效？', 'JWT 结构由点号 `.` 分隔的三段组成：`Header.Payload.Signature`。1. Header：说明令牌类型（JWT）与签名算法（如 HS256/RS256）；2. Payload：载荷信息（如 sub 业务主键、exp 过期时间戳、自定义用户信息），采用 Base64URL 编码（注意：明文可见，不可存放密码等敏感信息！）；3. Signature：数字签名，由 `HMACSHA256(Base64(Header) + "." + Base64(Payload), secret)` 计算得出，防篡改。无状态失效方案：因为 JWT 一旦签发在过期前天然有效，主动登出时可在 Redis 中维护一个【黑名单（Blacklist）】，将注销的 Token 存入 Redis 并设置与其剩余 TTL 一致的过期时间，网关鉴权时先查黑名单拦截。', 'JWT,内部结构,Token结构,主动注销,主动登出,JWT黑名单,注销,Payload,Signature', '计算机网络与安全', 1, 'it-190', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (191, '常见 Web 安全漏洞与防御手段：SQL 注入、XSS 跨站脚本、CSRF 跨站请求伪造', '1. SQL 注入：黑客通过构造恶意输入拼接 SQL 指令窃取或破坏数据库。防御：使用参数化查询（PreparedStatement，MyBatis 使用 `#{}` 严格参数绑定，禁止使用 `${}` 拼接）；2. XSS（跨站脚本攻击）：黑客向页面注入恶意 JS 代码并在其他用户浏览器执行以盗取 Cookie。防御：对所有用户输入输出进行 HTML 实体转义编码、设置 Cookie 的 `HttpOnly` 属性禁止 JS 读取、配置 CSP 内容安全策略；3. CSRF（跨站请求伪造）：黑客诱导用户点击第三方恶意链接并利用用户已有 Cookie 伪造合法请求。防御：采用 SameSite Cookie 策略、敏感接口使用 JWT 替换 Cookie、关键操作加入随机 Anti-CSRF Token 验证。', 'Web安全,SQL注入,XSS,CSRF,参数化查询,HttpOnly,SameSite,安全防御', '计算机网络与安全', 1, 'it-191', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (192, '对称加密算法（AES）与非对称加密算法（RSA/ECC）的原理与应用场景', '1. 对称加密（如 AES-256、DES）：加密和解密使用【同一套密钥】。优点：计算速度极快，CPU 损耗小，适合对海量业务数据、文件流或大文本进行加密存储与传输；缺点：密钥分发困难，若密钥泄露则全局失守；2. 非对称加密（如 RSA-2048、ECC 椭圆曲线）：拥有配对的【公钥】与【私钥】，公钥对外公开用于加密或验签，私钥严格保密用于解密或数字签名。优点：安全性极高，无需提前共享私钥；缺点：算法涉及大数质因数分解或离散对数计算，速度比对称加密慢数千倍，通常仅用于身份验签及在握手阶段协商对称会话密钥。', '对称加密,非对称加密,加密算法,加密区别,区别,AES,RSA,ECC,密钥协商,数据加密', '计算机网络与安全', 1, 'it-192', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (193, '常见时间复杂度与空间复杂度分析（大 O 表示法）核心规则是怎样的？', '大 O 表示法用于衡量算法随着输入规模 n 增长时的执行时间与资源消耗趋势。常见阶层由快到慢为：`O(1) 常数阶` < `O(log n) 对数阶`（二分查找） < `O(n) 线性阶`（单层循环） < `O(n log n) 线性对数阶`（快排、归并） < `O(n²) 平方阶`（双重冒泡） < `O(2^n) 指数阶` < `O(n!) 阶乘阶`。化简法则：1. 只保留最高阶项，忽略低阶项；2. 省略最高阶项前面的常数系数；3. 空间复杂度是指算法在运行过程中临时占用存储空间的大小趋势，递归调用栈深度亦属于空间消耗。', '时间复杂度,空间复杂度,大O表示法,算法分析,对数阶,线性阶,复杂度计算', '数据结构与算法', 1, 'it-193', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (194, '数组（Array）与链表（LinkedList）在内存分配与操作性能上的核心区别是什么？', '1. 内存分配：数组要求分配一块连续的物理内存空间；链表采用分散的离散节点，节点之间通过 next/prev 指针相连，内存利用更灵活且无固定大小限制；2. 随机访问（Read）：数组具备寻址公式 `address = base + index * size`，支持 O(1) 毫秒级随机访问；链表必须从头节点顺序向后遍历查找，时间复杂度为 O(n)；3. 插入与删除（Write）：数组在指定位置增删需要移动其后所有元素，平均时间复杂度为 O(n)；链表若已定位到目标节点，修改指针引用即可完成增删，时间复杂度为 O(1)；4. 缓存命中：数组在物理连续内存上有极高的 CPU 缓存行（Cache Line）局部性命中率。', '数组,链表,Array,LinkedList,区别,随机访问,内存连续,指针,增删性能', '数据结构与算法', 1, 'it-194', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (195, '哈希表（Hash Table）解决哈希冲突的常见方法有哪些？（链地址法与开放寻址法）', '当两个不同 Key 计算出相同的哈希槽位时产生哈希冲突。两大经典解法：1. 链地址法（Separate Chaining，拉链法）：每个哈希槽位保存一个链表头指针，所有冲突的元素以链表节点形式挂在对应槽位后面（Java HashMap 采用此方案，并在链表过长时升级为红黑树）；2. 开放寻址法（Open Addressing）：所有元素都保存在数组中，冲突时按某种探测策略寻找下一个未被占用的空槽位：- 线性探测（Linear Probing）：冲突后依次向后检查 `i+1, i+2...`；- 二次探测：按平方步长 `i+1², i-1²...` 检查；- 双重哈希：使用第二个哈希函数重新计算步长。', '哈希冲突,哈希表,链地址法,拉链法,开放寻址法,线性探测,二次探测', '数据结构与算法', 1, 'it-195', NOW())
