VALUES (196, '二叉树（Binary Tree）的三种深度遍历方式（前序、中序、后序）与层序遍历原理', '1. 前序遍历（Pre-order）：根节点 ➔ 左子树 ➔ 右子树，常用于树的复制与序列化；2. 中序遍历（In-order）：左子树 ➔ 根节点 ➔ 右子树，对于二叉搜索树（BST），中序遍历的结果严格单调递增；3. 后序遍历（Post-order）：左子树 ➔ 右子树 ➔ 根节点，常用于子节点计算与树的自底向上清理（如计算目录占用空间）；4. 层序遍历（Level-order，广度优先 BFS）：从根节点开始自顶向下、自左向右逐层访问，底层通常借助【队列（Queue）】先进先出特性实现。', '二叉树,前序,中序,后序,层序,层序遍历,二叉树遍历,前序遍历,中序遍历,后序遍历,BFS', '数据结构与算法', 1, 'it-196', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (197, '二叉搜索树（BST）、平衡二叉树（AVL）与红黑树（Red-Black Tree）的演进与平衡机制', '1. 二叉搜索树（BST）：左子树所有节点均小于根，右子树所有节点均大于根。若插入连续升序数据会退化成单向链表，查找复杂度从 O(log n) 恶化至 O(n)；2. AVL 树：严格平衡二叉树，任意节点左右子树高度差（平衡因子）不超过 1，查询极快，但每次插入删除频繁触发旋转（LL/RR/LR/RL），写开销大；3. 红黑树：弱平衡二叉树，通过 5 大红黑规则（根黑、叶黑、红子必黑、任意节点至叶子黑高相同）保证【最长路径不超过最短路径的 2 倍】，在插入删除更新（最多 3 次旋转）与查询效率之间取得了最出色的工程权衡。', '二叉搜索树,BST,平衡二叉树,AVL树,红黑树,树旋转,黑高,平衡机制', '数据结构与算法', 1, 'it-197', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (198, '快速排序（Quick Sort）与归并排序（Merge Sort）的核心思想与时间复杂度对比', '两者均基于分治思想（Divide and Conquer）：1. 快速排序：挑选一个基准值（Pivot），通过双指针分区使得左边元素小于基准、右边大于基准，然后递归处理左右两部分。平均时间复杂度 O(n log n)，最好 O(n log n)，最坏退化为 O(n²)（可通过随机三数取中规避），为原地排序（In-place，空间 O(log n)），是非稳定排序；2. 归并排序：将数组不断对半拆分为左右两半递归排序，最后通过双指针将两个有序子数组合并为一个有序数组。时间复杂度始终稳定为 O(n log n)，但需要额外 O(n) 辅助临时数组，是稳定排序。', '快速排序,归并排序,快排,分治法,时间复杂度,稳定排序,双指针,Pivot', '数据结构与算法', 1, 'it-198', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (199, '二分查找（Binary Search）的实现边界细节与在旋转有序数组中的应用', '标准二分实现核心边界：`int mid = left + (right - left) / 2`（防止整数加法溢出），循环条件为 `while (left <= right)`。在【旋转有序数组（如 [4,5,6,7,0,1,2]）】中查找目标值时，关键在于判断哪一半必然保持单调有序：每次计算 mid 后，若 `nums[left] <= nums[mid]`，说明前半部分绝对升序，检查 target 是否落在 `[nums[left], nums[mid])` 区间内；若在则收缩 `right = mid - 1`，否则在后半部分查找；反之说明后半部分绝对升序，同理比对收缩，时间复杂度依然保持 O(log n)。', '二分查找,BinarySearch,旋转有序数组,边界条件,整数溢出,对数时间', '数据结构与算法', 1, 'it-199', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (200, 'LRU（最近最少使用）缓存淘汰算法的实现原理是什么？如何基于哈希表与双向链表构建？', 'LRU 核心要求 `get` 与 `put` 操作均在 O(1) 时间复杂度内完成。底层数据结构为【哈希表（HashMap）+ 双向链表（Doubly Linked List）】：1. 双向链表按时间先后顺序串联数据节点，头部为最近访问节点，尾部为最久未访问节点；2. 哈希表的 Key 存储业务键，Value 直接存储指向链表中对应 Node 节点的引用指针；3. `get(key)`：在 HashMap 找到节点并将其摘下移到双向链表头部，返回值；4. `put(key, val)`：若已存在则更新值并移至链表头部；若不存在且容量已满，则将链表尾部（最久未使用）节点删除并在 HashMap 中同步移除，然后将新节点插入链表头部。', 'LRU,最近最少使用,缓存淘汰,双向链表,哈希表,O(1)复杂度,算法设计', '数据结构与算法', 1, 'it-200', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (201, '动态规划（Dynamic Programming）的核心解题步骤是怎样的？如何寻找状态转移方程？', '动态规划适用于具有【最优子结构】和【重叠子问题】的优化极值问题。标准解题四步法：1. 明确状态定义：明确数组 `dp[i]` 或 `dp[i][j]` 所代表的物理意义（如到达第 i 阶台阶的方案数、前 i 个物品容量为 j 的最大价值）；2. 寻找状态转移方程：推导 `dp[i]` 如何由规模更小的子问题（如 `dp[i-1]`、`dp[i-2]`）归纳计算得出；3. 确定边界条件与初始化：设定 `dp[0]`、`dp[1]` 的基础真值，防止越界；4. 确定遍历顺序并考虑空间压缩：自底向上循环计算，若只依赖前一项状态可利用滚动变量将 O(n) 空间优化为 O(1)。', '动态规划,DP,状态转移方程,最优子结构,重叠子问题,空间压缩,滚动数组', '数据结构与算法', 1, 'it-201', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (202, '深度优先搜索（DFS）与广度优先搜索（BFS）的算法思想与适用场景对比', '1. DFS（深度优先搜索）：基于“不撞南墙不回头”思想，沿着一条路径一直递归到底部，再回溯尝试其他分支。底层通过【函数递归调用栈】实现。空间复杂度取决于树的深度 O(h)。适用于全排列枚举、图的连通性分析、拓扑排序、数独与路径搜索；2. BFS（广度优先搜索）：基于“波纹扩散”思想，以当前节点为中心逐层向外平铺展开遍历。底层通过【队列（Queue）】先进先出实现。空间复杂度取决于单层最大宽度 O(w)。核心绝技在于：在无权图或等权图中能够天然保证【第一次访问到目标节点即为最短路径】。', 'DFS,BFS,深度优先搜索,广度优先搜索,回溯,最短路径,队列,递归栈', '数据结构与算法', 1, 'it-202', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (203, '大语言模型（LLM）底层核心架构 Transformer 与自注意力机制（Self-Attention）原理', '主流大模型（如 GPT、Gemini、Llama）均基于 Transformer 架构。核心灵魂是自注意力机制（Self-Attention）：将输入的每个 Token 映射为 Query（Q 查询）、Key（K 键）、Value（V 值）三个向量，通过点积注意力公式 `Attention(Q, K, V) = softmax((Q * K^T) / sqrt(d_k)) * V` 计算当前词与上下文中所有其他词的相关性权重得分。多头注意力（Multi-Head Attention）进一步让模型在不同投影子空间中同时关注不同层次的语义特征（如句法、代词指代、长程逻辑依赖），彻底突破了传统 RNN 无法并行训练与长文本遗忘的瓶颈。', 'Transformer,自注意力机制,SelfAttention,大模型架构,QKV,多头注意力,LLM', '人工智能与大模型', 1, 'it-203', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (204, '什么是大模型的 RAG（检索增强生成）？核心架构与向量数据库（Vector DB）的作用', 'RAG（Retrieval-Augmented Generation）解决了大模型知识时效性滞后、私有域数据缺失及“胡说八道（幻觉）”的痛点。核心三步流：1. 检索（Retrieval）：将用户提问转换为嵌入向量，在向量数据库（如 Milvus, Pinecone, Chroma）中利用余弦相似度或 HNSW 索引检索出最相关的 Top-K 私域文档切片；2. 增强（Augmentation）：将检索到的事实文档作为参考上下文（Context）动态拼装到 Prompt 提示词中；3. 生成（Generation）：引导大模型基于提供的上下文事实进行精准生成和引用回答。向量数据库负责在千万级高维向量空间内毫秒级完成近邻检索。', 'RAG,检索增强生成,向量数据库,VectorDB,私域知识库,TopK检索,提示词增强', '人工智能与大模型', 1, 'it-204', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (205, '文本向量化嵌入（Text Embedding）的原理是什么？余弦相似度如何计算？', 'Embedding 是将离散的高维自然语言文本（单词、句子或段落）映射为一个固定维度的低维连续稠密浮点数向量（如 768 或 1536 维空间坐标）。在嵌入空间中，语义越相近的文本，其几何向量距离越靠近。余弦相似度（Cosine Similarity）通过计算两个向量夹角的余弦值评估语义相关度：`cos(θ) = (A · B) / (||A|| * ||B||)`，取值范围在 -1 到 1 之间（在非负文本嵌入中通常在 0 到 1），值为 1 表示完全同向相关，0 表示正交无关联。', 'Embedding,文本嵌入,向量化,余弦相似度,语义搜索,高维向量,点积', '人工智能与大模型', 1, 'it-205', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (206, '大模型微调（Fine-Tuning）与提示工程（Prompt Engineering）的区别与选型策略', '1. Prompt 工程：不修改任何底层模型权重，仅通过精心设计指令、提供 Few-Shot 示例或构建 CoT 思维链引导模型输出。优点：零门槛、零算力成本、秒级迭代；缺点：受限于上下文窗口长度，难以注入海量专有垂直领域事实知识；2. 模型微调（Fine-Tuning）：在预训练大模型基础上输入标注好的特定领域问答数据集，更新部分或全部模型权重。优点：深度内化特定专业术语、行业规范格式与专属风格；缺点：算力昂贵、易发生灾难性遗忘。工业界黄金组合：【RAG 负责提供事实底料 + 提示工程规范输出 + 轻量微调定制输出风格】。', '大模型,微调,Prompt,提示工程,提示词工程,FineTuning,模型微调,选型策略', '人工智能与大模型', 1, 'it-206', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (207, '参数高效微调技术 LoRA（Low-Rank Adaptation）的核心数学原理与工程优势', '全量微调参数规模巨大（如 70B 模型微调需要数张 80GB A100/H100 显卡）。LoRA 核心思想：冻结大模型原本的预训练稠密权重矩阵 $W_0 \\in \\mathbb{R}^{d 	imes k}$，在旁边旁路增加两个低秩分解矩阵 $A \\in \\mathbb{R}^{r 	imes k}$ 和 $B \\in \\mathbb{R}^{d 	imes r}$（其中秩 $r \\ll \\min(d, k)$，通常取 8 或 16），前向传播计算为 $W = W_0 + rac{lpha}{r} (B \\cdot A)$。训练时仅更新旁路的小矩阵 $A$ 与 $B$，可训练参数量骤降至原模型的 1% 以下，显存占用降低 70%，且同一底座大模型可灵活拔插挂载多个不同业务方向的 LoRA 权重文件。', 'LoRA,低秩微调,低秩适配,省显存,显存优化,PEFT,高效微调,参数冻结', '人工智能与大模型', 1, 'it-207', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (208, '什么是 AI Agent（智能体）？核心四大要素（规划、记忆、工具、行动）是怎样的？', 'AI Agent 是以大语言模型为大脑核心、具备自主感知环境、推理规划并自主调用外部工具达成复杂目标的智能实体。核心四大架构支柱：1. 目标规划（Planning）：任务分解（将大目标拆解为子步骤链如 ReAct / Reflexion）与自我反思（对执行结果复盘修正）；2. 记忆系统（Memory）：短期记忆（当前对话上下文窗口）与长期记忆（通过向量库存储历史经验）；3. 工具调用（Tools）：利用 Function Calling 调用外部搜索、数据库查询、运行代码与执行 API；4. 行动执行（Action）：根据规划调用工具并将外部反馈重新灌入模型进行下一步推演。', 'AIAgent,智能体,规划,记忆,工具调用,FunctionCalling,ReAct框架,智能体架构', '人工智能与大模型', 1, 'it-208', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (209, '大模型生成控制参数解析：Temperature、Top_p、Top_k 分别控制什么？如何科学调参？', '1. Temperature（温度值，0~2）：控制输出概率分布的平滑度。值越低（如 0.1~0.3），模型越保守确定，生成答案越严谨精确（适合写代码、数学推理、提取数据）；值越高（如 0.8~1.2），低概率词越有机会被选中，回答越具创造性和发散性（适合诗歌、小说创作）；2. Top_p（核采样，0~1）：按词表中词的概率降序排列，仅在累积概率达到 p 的候选词集中采样；3. Top_k（候选词数）：仅在概率最高的前 k 个词中挑选。调参法则：一般建议固定 Top_p 为 0.9，仅微调 Temperature 即可达到理想效果。', 'Temperature,Top_p,Top_k,采样参数,模型生成,调参技巧,随机性,确定性', '人工智能与大模型', 1, 'it-209', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (210, '如何解决大语言模型“幻觉（Hallucination）”问题？工业落地有哪些约束手段？', '幻觉是指大模型一本正经地捏造不存在的事实或推导错误。工业界五重防御手段：1. RAG 检索增强：强制模型根据私域真实文档回答，并在 Prompt 中严厉声明“若文档中未提及请回答不知道，禁止臆测”；2. 约束输出格式：通过 Structured Outputs / JSON Schema 强制模型按既定结构输出字段，杜绝散漫发挥；3. Few-Shot 优质示例引导：提供真实准确的正反示例约束推演逻辑；4. 降低 Temperature（如设为 0~0.2）：极大收敛随机采样；5. 双智能体对抗审核（Guardrails）：引入专门的 Critic 评审智能体，对照原始事实材料对初版答案进行事实验证和打分过滤。', '大模型,幻觉,大模型幻觉,解决幻觉,幻觉问题,防幻觉,Hallucination,RAG约束', '人工智能与大模型', 1, 'it-210', NOW())
