INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (213, '面向对象设计的 SOLID 五大原则是什么？在软件工程中如何落地实践？', 'SOLID 原则是面向对象设计与可维护代码的黄金基石：1. S - 单一职责原则（Single Responsibility）：一个类应该只有一个引起它变化的原因，避免臃肿的“上帝类”；2. O - 开闭原则（Open-Closed）：对扩展开放，对修改关闭。通过接口和抽象类扩展新功能，禁止修改原有测试通过的底层源码；3. L - 里氏替换原则（Liskov Substitution）：子类必须能够无缝替换其基类且不会破坏程序正确性，子类不应覆盖父类的非抽象已实现方法；4. I - 接口隔离原则（Interface Segregation）：客户端不应被强迫依赖它不需要的胖接口，应将大接口拆分为细粒度小接口；5. D - 依赖倒置原则（Dependency Inversion）：高层模块不应依赖低层模块，二者都应依赖抽象接口，面向接口编程。', 'SOLID原则,单一职责,开闭原则,里氏替换,接口隔离,依赖倒置,面向对象设计', '系统架构与设计模式', 1, 'it-213', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
