VALUES (220, '微服务架构下服务雪崩效应产生原因与防范措施（线程池隔离、信号量隔离与熔断器状态机）', '服务雪崩是指下游基础服务由于响应变慢或不可用，导致上游调用方大量请求线程积压阻塞，雪球越滚越大直至连锁导致全站微服务集群级联崩溃。防范三道防线：1. 资源隔离：- 线程池隔离：为每个依赖服务分配独立的专用线程池，某个服务瘫痪只耗尽自己的线程池，不影响其他业务；- 信号量隔离：使用轻量原子计数器控制并发数，无线程切换开销；2. 熔断机制：通过熔断器状态机（关闭 Closed ➔ 打开 Open ➔ 半开 Half-Open）动态监控错误率，达到阈值直接熔断进入降级逻辑（快速失败，不耗时间等待），半开状态尝试少量请求探测恢复；3. 严格设置全链路超时时间与重试上限。', '服务雪崩,雪崩效应,熔断器,线程池隔离,信号量隔离,快速失败,状态机,容错机制', '系统架构与设计模式', 1, 'it-220', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (221, '领域驱动设计（DDD）的核心概念：战略设计与战术设计是如何落地的？', 'DDD（Domain-Driven Design）是应对复杂业务软件系统的架构方法论：1. 战略设计（宏观切分）：建立统一通用语言（Ubiquitous Language），划分核心域、通用域与支撑域，通过【限界上下文（Bounded Context）】明确微服务边界与上下文映射关系（Context Map）；2. 战术设计（微观建模）：- 实体（Entity）：具有唯一业务身份标识且状态随生命周期演变的领域对象；- 值对象（Value Object）：没有独立标识，仅由属性值定义的不可变只读对象（如金额、地址）；- 聚合（Aggregate）与聚合根（Aggregate Root）：强一致性边界，外部只能通过聚合根进行访问与状态修改；- 领域服务（Domain Service）与仓储（Repository）：协调多个聚合并实现与底层存储技术的解耦。', 'DDD,领域驱动设计,限界上下文,聚合根,实体,值对象,战略设计,战术设计,领域建模', '系统架构与设计模式', 1, 'it-221', NOW())
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`), `answer` = VALUES(`answer`), `keywords` = VALUES(`keywords`), `category` = VALUES(`category`), `status` = VALUES(`status`), `update_time` = NOW();
INSERT INTO `cs_knowledge` (`id`, `question`, `answer`, `keywords`, `category`, `status`, `legacy_id`, `update_time`)
VALUES (222, '读写分离与 CQRS（命令查询职责分离）架构在千万级并发系统中的应用', '1. 读写分离：在数据层主库（Master）负责事务写操作，多个从库（Slave）负责处理海量只读查询，通过数据库主从复制保持同步；2. CQRS 架构（Command Query Responsibility Segregation）：在应用与模型层将写操作（Command，强一致、领域驱动校验、写入事务型 DB）与读操作（Query，按查询视图专门设计扁平反范式模型、直接读取 Redis / Elasticsearch 高性能引擎）彻底解耦分离。优势在于：彻底解放读写模型的互相牵制，读模型针对复杂多表关联、聚合统计与高并发实时查询进行极限性能优化，写模型保持极致纯粹的业务逻辑与事务安全。', '读写分离,CQRS,命令查询分离,架构设计,主从同步,Elasticsearch读模型,高并发架构', '系统架构与设计模式', 1, 'it-222', NOW())
